CREATE OR REPLACE FUNCTION company_checkout_allowance_private.normalize_choices(cid uuid, wid uuid, choices jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare item jsonb; matched jsonb;
begin
 if choices is null then return null;end if;
 if auth.uid() is null or private.account_access_allowed() is not true or not exists(
 select 1 from public.company_members where company_id=cid and user_id=auth.uid())
 then raise exception 'company allowance report unavailable' using errcode='42501';end if;
 if jsonb_typeof(choices) is distinct from 'object' or (select count(*) from jsonb_object_keys(choices))<>2
 or choices->'contract_version' is distinct from '1'::jsonb or jsonb_typeof(choices->'items') is distinct from 'array'
 or jsonb_array_length(choices->'items')>303 then raise exception 'invalid versioned company selections' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(choices->'items') x group by x->>'origin',(x->>'id')::uuid having count(*)>1)
 or exists(select 1 from jsonb_array_elements(choices->'items') x group by x->>'origin' having count(distinct x->>'registration_version')>1)
 or exists(select 1 from jsonb_array_elements(choices->'items') x group by x->>'name_snapshot' having count(*)>1)
 then raise exception 'ambiguous company allowance selections' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(choices->'items') loop
  matched:=company_checkout_allowance_private.registered_item(cid,wid,item);
 end loop;
 return choices;
end $function$

CREATE OR REPLACE FUNCTION company_checkout_allowance_private.validate_labels(cid uuid, wid uuid, new_text text, choices jsonb, prior_text text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare selected text[]; prior text[]; present text[];
begin
 if choices is null then return;end if;
 perform company_checkout_allowance_private.normalize_choices(cid,wid,choices);
 if length(coalesce(new_text,''))>1048576 then raise exception 'allowance labels exceed range' using errcode='22023';end if;
 select coalesce(array_agg(value->>'name_snapshot'),'{}') into selected from jsonb_array_elements(choices->'items');
 select coalesce(array_agg(distinct btrim(v)) filter(where btrim(v)<>''),'{}') into prior
 from unnest(string_to_array(coalesce(prior_text,''),E'\n')) v;
 select coalesce(array_agg(distinct btrim(v)) filter(where btrim(v)<>''),'{}') into present
 from unnest(string_to_array(coalesce(new_text,''),E'\n')) v;
 if not selected<@present or not present<@(prior||selected) then
  raise exception 'allowance labels do not match explicit company choices' using errcode='22023';end if;
end $function$

CREATE OR REPLACE FUNCTION private.save_daily_report_vehicle_usage(p_report_id uuid, p_worker_id uuid, p_vehicle_id uuid, p_route_assignment_id uuid, p_odometer_km numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_company uuid;
  v_status text;
  v_current numeric;
  scope_before jsonb;
begin
  if v_user is null then raise exception 'ログインが必要です'; end if;

  select m.company_id into v_company
  from public.company_members m
  where m.user_id=v_user
  limit 1;
  if v_company is null then raise exception '会社への所属が必要です'; end if;

  if not exists(select 1 from public.daily_reports where id=p_report_id and company_id=v_company) then raise exception '日報を確認できません'; end if;
  scope_before:=payroll_scope_private.report_sources(p_report_id);
  perform payroll_scope_private.lock_scopes(scope_before->'scopes');
  select d.status into v_status
  from public.daily_reports d
  where d.id=p_report_id and d.company_id=v_company
  for update;
  if payroll_scope_private.report_sources(p_report_id) is distinct from scope_before then raise exception 'daily report payroll scope changed' using errcode='40001'; end if;
  if v_status is null then raise exception '日報を確認できません'; end if;
  if v_status<>'draft' then raise exception '確定済み日報は直接変更できません'; end if;

  if not exists(
    select 1 from public.daily_report_workers w
    where w.report_id=p_report_id and w.worker_id=p_worker_id
  ) then
    raise exception '日報の社員情報を確認できません';
  end if;

  if p_vehicle_id is not null and not exists(
    select 1 from public.vehicles v
    where v.id=p_vehicle_id and v.company_id=v_company and v.is_active=true
  ) then
    raise exception '車両を確認できません';
  end if;

  if p_route_assignment_id is not null and not exists(
    select 1 from public.route_assignments r
    where r.id=p_route_assignment_id
      and r.company_id=v_company
      and r.is_active=true
  ) then
    raise exception 'ルートを確認できません';
  end if;

  if p_odometer_km is not null and p_odometer_km<0 then
    raise exception '走行距離を確認してください';
  end if;

  if p_vehicle_id is not null and p_odometer_km is not null then
    select v.odometer_km into v_current
    from public.vehicles v
    where v.id=p_vehicle_id and v.company_id=v_company
    for update;

    if p_odometer_km<v_current then
      raise exception '現在の走行距離より小さい数値は登録できません';
    end if;

    update public.vehicles
    set odometer_km=p_odometer_km,
        updated_by=v_user,
        updated_at=now()
    where id=p_vehicle_id and company_id=v_company;
  end if;

  update public.daily_report_workers
  set vehicle_id=p_vehicle_id,
      route_assignment_id=p_route_assignment_id,
      odometer_km=p_odometer_km
  where report_id=p_report_id and worker_id=p_worker_id;
end
$function$
